/bin/bash -lc "node --input-type=module <<'NODE'
import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { connect } from 'node:net'

let received
let resolveEvent
const event = new Promise((resolve) => { resolveEvent = resolve })
const analytics = createServer((request, response) => {
  let body = ''
  request.on('data', (chunk) => { body += chunk })
  request.on('end', () => {
    received = { url: request.url, body: JSON.parse(body) }
    resolveEvent()
    setTimeout(() => { response.writeHead(200).end() }, 1500)
  })
})
await new Promise((resolve) => analytics.listen(0, '127.0.0.1', resolve))
const analyticsPort = analytics.address().port
const next = spawn('node', ['node_modules/next/dist/bin/next', 'start', '-p', '32045'], {
  env: { ...process.env, ANALYTICS_ENDPOINT: "'`http://127.0.0.1:${analyticsPort}/events` },
  stdio: '"'ignore',
})
try {
  let ready = false
  for (let attempt = 0; attempt < 50; attempt++) {
    ready = await new Promise((resolve) => {
      const socket = connect(32045, '127.0.0.1')
      socket.once('connect', () => { socket.destroy(); resolve(true) })
      socket.once('error', () => resolve(false))
    })
    if (ready) break
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
  if ("'!ready) throw new Error('"'Next server did not start')
  const started = Date.now()
  const response = await fetch('http://127.0.0.1:32045/')
  const html = await response.text()
  const elapsed = Date.now() - started
  await Promise.race([event, new Promise((_, reject) => setTimeout(() => reject(new Error('No analytics event received')), 3000))])
  if (response.status "'!== 200 || !html.includes('"'Welcome')) throw new Error('Welcome response failed')
  if (elapsed >= 1500) throw new Error("'`Response took ${elapsed} ms, analytics delay was 1500 ms`)
  if (received.url !== '"'/events' || received.body.event "'!== '"'page_view' || received.body.path "'!== '"'/') throw new Error('Unexpected analytics payload')
  process.stdout.write("'`Response ${response.status} in ${elapsed} ms; analytics received ${JSON.stringify(received.body)}'"\\n"'`)
} finally {
  next.kill('"'SIGTERM')
  analytics.close()
}
NODE"
